      "path": "package.json",
      "content": "{\n  \"name\": \"@goodandready/dsh-russian-lang\",\n  \"version\": \"0.4.22\",\n  \"description\": \"Полная русская локализация DeepSeek Harness (DSH): ядро v0.2.2-rc.1 + 85 плагинов экосистемы, 13,055 UI keys, 100% покрытие экосистемы, естественный русский язык\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"import\": \"./lib/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./pure\": {\n      \"types\": \"./lib/pure.d.ts\",\n      \"import\": \"./lib/pure.js\"\n    },\n    \"./locales\": \"./lib/locales.js\",\n    \"./commands\": {\n      \"types\": \"./lib/commands.d.ts\",\n      \"import\": \"./lib/commands.js\"\n    },\n    \"./safe-locale-proxy\": {\n      \"types\": \"./lib/safe-locale-proxy.d.ts\",\n      \"import\": \"./lib/safe-locale-proxy.js\"\n    },\n    \"./ui\": {\n      \"types\": \"./lib/ui/index.d.ts\",\n      \"import\": \"./lib/ui/index.js\"\n    },\n    \"./package.json\": \"./package.json\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\"\n  },\n  \"files\": [\n    \"lib\",\n    \"!lib/client.template.js\",\n    \"!lib/locales/plugins-en\",\n    \"!lib/locales/core.json\",\n    \"bin\",\n    \"glossary.json\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.ru.md\",\n    \"README.zh.md\",\n    \"DESIGN.md\",\n    \"NOTICE\",\n    \"LICENSE\",\n    \"supported-inventory.json\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-slots\"\n      ]\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-rc.2\": \"compatible\",\n        \"0.2.1-rc.3\": \"compatible\",\n        \"0.2.1-rc.4\": \"compatible\",\n        \"0.2.1-rc.5\": \"compatible\",\n        \"0.2.2-rc.1\": \"compatible\"\n      },\n      \"dsh\": \"0.2.0-rc.2 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\"\n    }\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"i18n\",\n    \"locale\",\n    \"russian\"\n  ],\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"node\": \">=22\",\n    \"dsh\": \"0.2.0-rc.2 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\"\n  },\n  \"scripts\": {\n    \"test\": \"node --check lib/index.js && node --check lib/client.js\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.4 || ~4.0.5\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.0-rc.2 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.0-rc.2 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.0-rc.2 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-commands\": \">=0.2.1-rc.2 <0.3.0\",\n    \"@deepseek-ai/dsh-home-paths\": \"0.2.0-rc.2 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.0-rc.2 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.0-rc.2 || >=0.2.1-rc.2 <0.2.2-0 || >=0.2.2-0 <0.2.3-0\",\n    \"@deepseek-ai/schemastery\": \"~3.18.4 || ~3.18.5\",\n    \"react\": \"^18.2.0\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/GooDAnDReaDY/dsh-russian-lang.git\"\n  },\n  \"homepage\": \"https://github.com/GooDAnDReaDY/dsh-russian-lang#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/GooDAnDReaDY/dsh-russian-lang/issues\"\n  },\n  \"bin\": {\n    \"dsh-i18n\": \"./bin/dsh-i18n.mjs\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-host-webserver\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-commands\": {\n      \"optional\": true\n    }\n  },\n  \"types\": \"./lib/index.d.ts\",\n  \"sideEffects\": false,\n  \"dependencies\": {}\n}\n"
